parameters.query:
INSERT INTO ai_test_sessions (channel, scenario, tester_number, bot_number, meta)
VALUES ('voice', $1::jsonb, $2, $3, $4::jsonb)
RETURNING id;

parameters.jsCode:
const body = $('Start Test').first().json.body;
const s = body.scenario || {};
const sessionId = $input.first().json.id;
const call = {
  from_number: body.from_number,
  to_number: body.to_number,
  metadata: { ai_test_session_id: String(sessionId) },
  retell_llm_dynamic_variables: {
    persona: s.persona || 'A regular customer.',
    goal: s.goal || 'Get your question answered.',
    scenario_name: s.name || ''
  }
};
if (body.tester_agent_id) call.override_agent_id = body.tester_agent_id;
return [{ json: { session_id: sessionId, retell_body: call } }];

// No waiting test for this number -> empty answer: Retell uses the number's normal inbound agent.
const r = $input.first().json;
if (!r.session_id) return [{ json: { call_inbound: {} } }];
const s = r.scenario || {};
const call_inbound = {
  dynamic_variables: {
    persona: String(s.persona || 'A regular customer.'),
    goal: String(s.goal || 'Get your question answered.'),
    scenario_name: String(s.name || '')
  },
  metadata: { ai_test_session_id: String(r.session_id) }
};
if (r.answer_agent_id) call_inbound.override_agent_id = r.answer_agent_id;
return [{ json: { call_inbound } }];

// Only our test calls' 'call_ended' events (they carry ai_test_session_id)
const b = $input.first().json.body || {};
const call = b.call || {};
const sid = call.metadata?.ai_test_session_id;
if (b.event !== 'call_ended' || !sid) return [];
return [{ json: { session_id: sid, call } }];

const r = $input.first().json;
// Grade calls that really happened, even if someone pressed Stop meanwhile.
if (!r.session_id || !['running', 'aborted'].includes(r.status)) return [];
const call = $('Only Tester Call Ended').first().json.call;

// Our agent (tester or answering agent) = CUSTOMER; the other side = the client's BOT
let history = (call.transcript_object || []).map(t => ({
  role: t.role === 'agent' ? 'tester' : 'bot',
  content: t.content
}));
if (!history.length && call.transcript) {
  history = call.transcript.split('\n').filter(Boolean).map(l => ({
    role: l.startsWith('Agent:') ? 'tester' : 'bot',
    content: l.replace(/^(Agent|User):\s*/, '')
  }));
}
const durSec = call.end_timestamp && call.start_timestamp
  ? Math.round((call.end_timestamp - call.start_timestamp) / 1000) : null;

return [{ json: {
  session_id: r.session_id,
  channel: 'voice',
  scenario: r.scenario,
  turns: history.filter(h => h.role === 'tester').length,
  history,
  end_reason: call.disconnection_reason || 'call_ended',
  extra: { call_id: call.call_id, duration_sec: durSec, recording_url: call.recording_url || null }
}}];

const c = $input.first().json;
const s = c.scenario || {};
const transcript = (c.history || [])
  .map(m => (m.role === 'tester' ? 'CUSTOMER' : 'BOT') + ': ' + m.content)
  .join('\n');
const checks = (s.checks || []).map((x, i) => (i + 1) + '. ' + x).join('\n');
const outbound = s.bot_starts === true;
const channelNote = 'The conversation was a PHONE CALL; the transcript comes from speech-to-text, so ignore small transcription errors.'
  + (outbound ? ' This was an OUTBOUND call: the BOT phoned the CUSTOMER.' : '');

const system = [
  'You are a strict QA evaluator for customer-facing AI assistants.',
  'You read a conversation between a simulated CUSTOMER and a business BOT and grade the BOT only.',
  channelNote,
  'Be objective. A check passes only if the transcript clearly shows it.',
  'If the transcript is empty or the bot never replied, the test fails.',
  'For every check that fails, the "reason" must quote the BOT\'s exact words from the transcript (or say "the bot never said/did this").',
  'Return ONLY valid JSON in this shape:',
  '{',
  '  "overall_pass": true/false,',
  '  "score": 0-100,',
  '  "goal_achieved": true/false,',
  '  "checks": [{"check": "...", "pass": true/false, "reason": "..."}],',
  '  "issues": ["short description of each problem found"],',
  '  "summary": "2-3 sentence summary"',
  '}'
].join('\n');

const user = [
  'SCENARIO: ' + (s.name || ''),
  'CUSTOMER PERSONA: ' + (s.persona || ''),
  'CUSTOMER GOAL: ' + (s.goal || ''),
  'TEST ENDED BECAUSE: ' + c.end_reason,
  '',
  'CHECKS TO GRADE:',
  checks || '(none given - judge general quality: accuracy, politeness, stays on task, no hallucination)',
  '',
  'TRANSCRIPT:',
  transcript || '(empty)'
].join('\n');

return [{ json: { ...c, transcript, openai_body: {
  model: s.judge_model || 'gpt-4o',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }]
}}}];

const ctx = $('Build Judge Request').first().json;
let result;
try {
  result = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  result = { overall_pass: false, score: 0, summary: 'Judge output parse failed', raw: $input.first().json };
}
result.end_reason = ctx.end_reason;
result.turns = ctx.turns;
result.transcript = ctx.transcript;
if (ctx.extra) result.extra = ctx.extra;
return [{ json: {
  session_id: ctx.session_id,
  status: result.overall_pass ? 'passed' : 'failed',
  history: ctx.history || [],
  result
}}];
